//go:build !tinygo

// Checks on the committed generated files. They read the sources and re-run the
// generator, neither of which is a TinyGo target.

package dynamofixture_test

import (
	"bytes"
	"os"
	"strings"
	"testing"

	"github.com/shibukawa/tinybind-go/generator"
)

// fixtureOptions is what generated this package. The Context query API is on,
// so both generated surfaces run against the fake server here; the default,
// where no wrapper is generated at all, is covered in the generator's own
// tests.
func fixtureOptions() generator.Options {
	options := generator.DefaultOptions()
	options.DynamoContextAPI = true
	return options
}

func TestGeneratedFilesHaveNoReflect(t *testing.T) {
	for _, name := range []string{"dynamobind_gen.go", "dynamoquery_gen.go"} {
		source, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		if bytes.Contains(source, []byte(`"reflect"`)) || bytes.Contains(source, []byte("reflect.")) {
			t.Errorf("%s reaches for reflect", name)
		}
	}
}

// TestCommittedCodecIsCurrent fails when a checked-in file no longer matches
// what this generator emits, so a stale codec is a test failure rather than a
// wrong item or a wrong query.
func TestCommittedCodecIsCurrent(t *testing.T) {
	options := fixtureOptions()
	plan, err := generator.AnalyzeDynamoItemsWithOptions(".", options)
	if err != nil {
		t.Fatalf("analyze items: %v", err)
	}
	items, err := generator.EmitDynamoItems(plan, true)
	if err != nil {
		t.Fatalf("emit items: %v", err)
	}
	assertGenerated(t, "dynamobind_gen.go", items)

	queries, err := generator.New(options).EmitDynamoQueriesFor(".")
	if err != nil {
		t.Fatalf("emit queries: %v", err)
	}
	assertGenerated(t, "dynamoquery_gen.go", queries)
}

// assertGenerated compares a committed file with freshly generated bytes,
// ignoring the generation stamp. The stamp records the inputs of the run that
// wrote the file, so it differs by construction and says nothing about whether
// the code is current.
func assertGenerated(t *testing.T, name string, want []byte) {
	t.Helper()
	got, err := os.ReadFile(name)
	if err != nil {
		t.Fatal(err)
	}
	if withoutStamp(got) != withoutStamp(want) {
		t.Fatalf("%s is out of date; regenerate it\n--- committed ---\n%s\n--- generated ---\n%s", name, got, want)
	}
}

func withoutStamp(source []byte) string {
	var kept []string
	for _, line := range strings.Split(string(source), "\n") {
		if strings.HasPrefix(line, "// tinybind:generated") {
			continue
		}
		kept = append(kept, line)
	}
	return strings.TrimSpace(strings.Join(kept, "\n"))
}
